mapper.select:
select distinct sr.user_name AS userName, sr.emp_name AS empName, sr.emp_no AS empNo, em.phone_no AS phoneNo, em.email AS email, em.position_name, em.org_name AS orgName from ytsafety_sys_responsible sr inner join safety_employee_message em on em.emp_no = sr.emp_no where sr.status=0 and sr.del_flag=0 and sr.user_id in (select user_id from ytsafety_sys_user_depart where depart_code=#{departCode} ) and sr.user_id in (select user_id from safety_sys_user_role where role_code in
#{item}
)

SELECT COUNT(1) > 0 FROM ytsafety_sys_responsible sr INNER JOIN safety_sys_user_role sur ON sr.user_id = sur.user_id WHERE sr.status=0 and sr.del_flag = 0 AND sr.emp_no = #{empNo} AND sur.role_code IN
#{item}
AND sur.del_flag = 0

select * from safety_sys_user_role us
left join safety_sys_user u on u.id = us.user_id
where u.emp_no = #{empNo}

    and us.role_code in

        #{item}

SELECT DISTINCT u.* FROM safety_sys_user_role ur INNER JOIN safety_sys_user u ON u.id = ur.user_id AND u.delete_falg = 0 INNER JOIN ytsafety_sys_user_factory uf ON uf.user_id = ur.user_id WHERE ur.role_code IN
#{item}
AND uf.factory_code = #{factoryCode};

select u.* from  safety_sys_user u
left join safety_sys_user_role ur on ur.user_id = u.id and u.delete_falg = 0
where ur.role_code =  #{safetyOfficer} and u.id = #{userId}

select t.id, t.location_name, t.location_code,
       t.org_name as orgName, t.org_code as orgCode, t.org_id as orgId,
       t.factory_id as factoryId, t.factory_code as factoryCode, t.factory_name as factoryName,
       t.area_id as areaId, t.area_name as areaName,
       sf.field_code as areaCode
from ytsafety_location_info t
left join safety_field_manage sf on sf.id = t.area_id and sf.delete_falg = 0
where t.del_flag = 0 and t.status=0

    and t.factory_id = #{factoryId}


    and t.area_id = #{areaId}


    and t.org_id = #{orgId}


    and t.org_code = #{orgCode}
